Let $Q$ be a mean-field variational posterior and $P=\mathcal{N}(\mathbf{0},\mathbf{I})$ denote the prior over a neural network with $L$ hidden layers and $M$ neurons per hidden layer.
    Suppose $\phi_{\text{e}}=\alpha$ for some $\alpha \in \mathbb{R}$ and $\phi\colon \mathbb{R} \to \mathbb{R}$ is $1$-Lipschitz.
    Let $\mathbf{x} \in \mathbb{R}^{D_{\text{i}}}$ and let $\widetilde{\mathbf{f}}_{\theta}(\mathbf{x}) = \mathbf{f}_\theta(\mathbf{x}) - \tfrac\alpha{\sqrt{M}}\mathbf{W}_{L+1}\mathbf{1} - \mathbf{b}_{L+1}$ denote the network output excluding final bias and even part of the final activation. Then 
    \begin{equation}
        \left\| \mathbb{E}_Q[\tilde{\mathbf{f}}_{\bm{\uptheta}}^2(\mathbf{x})] - \mathbb{E}_P[\tilde{\mathbf{f}}_{\bm{\uptheta}}^2(\mathbf{x})] \right\|_\infty
        \le
            c_1L^{1/2} \rho_{\alpha, M}^L
            \frac
                {\alpha^2 + 1 + \tfrac1{D_{\text{i}}}\left\| \mathbf{x} \right\|_2^2}
                {\sqrt{M}}  
            \sqrt{\operatorname{KL}(\ensuremath{Q}, \ensuremath{P})} (2\operatorname{KL}(\ensuremath{Q}, \ensuremath{P}) \lor 1)^{L+\tfrac12},
    \end{equation}
    where $c_1 = 16 + 25\sqrt{2} \in (51, 52)$ and where $\rho_{\alpha, M} \in (17, 97)$ is defined in 35.

Suppose $\ensuremath{Q}$ is mean-field Gaussian, $\ensuremath{P}=\mathcal{N}(\mathbf{0}, \mathbf{I})$, $\phi_{e}=\alpha$, with $\alpha \in \mathbb{R}$ and $\phi$ is $1$-Lipschitz. Then,
\begin{align}
    \left\| \mathbb{E}[\phi_{\text{o}}(\mathbf{z}_L(\mathbf{x}))] \right\|_2
    &\le 2L(2 + \left | \alpha \right | + \tfrac{1}{\sqrt{D_{\text{i}}}}\left\| \mathbf{x} \right\|_2)(2 + 2c)^{L - 1}\sqrt{2\operatorname{KL}(Q,P)}(\sqrt{2\operatorname{KL}(Q,P)} \lor 1)^{L - 1},
\end{align}
where $c>0$ is a universal constant.

Let $a, b\in \mathbb{R}$ and $\{c_\ell\}_{\ell=1}^L$, with $c_\ell \in \mathbb{R}$. Suppose, $c_\ell \le a c_{\ell-1} + b$ with $a, b \ge 0$ for $h > 1$.
    Then for $2 \leq \ell \leq L$
    \begin{equation}
        c_\ell \le a^{\ell - 1} c_1 + (1 + a)^{\ell - 2} b.
    \end{equation}

Define $K = \sqrt{2\operatorname{KL}(\ensuremath{Q},\ensuremath{P})}$. Then for $1 \le \ell \leq L$
\begin{align}
     \tfrac1{\sqrt{M}}\mathbb{E}_Q[\left\| \mathbf{z}_\ell \right\|_2] &\le (2 + \left | \alpha \right | + \tfrac1{\sqrt{D_{\text{i}}}}\left\| \mathbf{x} \right\|_2)(2 + 2c)^\ell(K \lor 1)^\ell,
\end{align}
where $c$ is the same absolute constant from 15.

Define $K = \sqrt{2\operatorname{KL}(\ensuremath{Q},\ensuremath{P})}$. Then for $1 \le \ell \leq L$
\begin{align}
     \left\| \mathbb{E}_Q[\mathbf{z}_\ell] \right\|_2 &\le 2\ell (2 + \left | \alpha \right | + \tfrac1{\sqrt{D_{\text{i}}}}\left\| \mathbf{x} \right\|_2)(2 + 2c)^{\ell-1}K(K \lor 1)^{\ell-1},
\end{align}
where $c$ is the same absolute constant from 15

Assume the conditions of 18.
    Then 
    \begin{align}
        &\mathbb{E}[\left\| \tfrac1{\sqrt{M}}\mathbf{W} (\phi_2 + \alpha)(\mathbf{z}) + \mathbf{b} \right\|_2]  \\
        &\qquad\le (\tfrac1{\sqrt{M}}\mathbb{E}[\left\| \mathbf{z} \right\|_2] + \left | \alpha \right |) (\left\| \mathbb{E}[\mathbf{W}] \right\|_2 + c\sigma \sqrt{M})  + \left\| \mathbb{E}[\mathbf{b}] \right\|_2+ c \sigma \sqrt{M}.
    \end{align}

Let $\phi_1,\phi_2\colon \mathbb{R} \to \mathbb{R}$ be $1$-Lipschitz and odd.
    Let the triple $(\mathbf{W}, \mathbf{z}, \mathbf{b})$ be  (possibly dependent) random variables such that
    \begin{equation}
        (\mathbf{W} - \mathbb{E}[\mathbf{W}], \mathbf{z}, \mathbf{b} - \mathbb{E}[\mathbf{b}])
        \overset{\text{d}}{=}
        (-(\mathbf{W} - \mathbb{E}[\mathbf{W}]), \mathbf{z}, -(\mathbf{b} - \mathbb{E}[\mathbf{b}]))
    \end{equation}
    Then
    \begin{align}
        &\left\| \mathbb{E}[\phi_1(\mathbf{W} \phi_2(\mathbf{z}) + \mathbf{b})] \right\|_2 
    \le \left\| \mathbb{E}[\mathbf{W}] \right\|_{\text{F}}\mathbb{E}[\left\| \mathbf{z} \right\|_2] + \mathbb{E}[\left\| \mathbf{W} - \mathbb{E}[\mathbf{W}] \right\|_2] \left\| \mathbb{E}[\mathbf{z}] \right\|_2 + \left\| \mathbb{E}[\mathbf{b}] \right\|_2
    \end{align}

Let $\phi_1, \phi_2 \colon \mathbb{R} \to \mathbb{R}$ be $1$-Lipschitz and odd.
    Then
    \begin{align}
        &\left\| \phi_1(\mathbf{W} \phi_2(\mathbf{z}) + \mathbf{b}) - \phi_1(\mathbf{W}' \phi_2(\mathbf{z}') + \mathbf{b}') \right\|_2  \\
        &\qquad\le
            \left\| \mathbf{z} \right\|_2 \left\| \mathbf{W} - \mathbf{W}' \right\|_{\text{F}}
            + \left\| \mathbf{W}' \right\|_2 \left\| \mathbf{z} - \mathbf{z}' \right\|_2
            + \left\| \mathbf{b} - \mathbf{b}' \right\|_2.
    \end{align}

Let $\mathbf{A} \in \mathbb{R}^{I \times J}$ be a zero-mean random matrix with independent Gaussian entries with variances bounded by $\sigma^2$.
    Then
    \begin{equation}
        \mathbb{E}[\left\| \mathbf{A} \right\|_2] \le 2 \sigma \sqrt{I \lor J}.
    \end{equation}
    Moreover, if the variances of the entries of $\mathbf{A}$ are all equal to one, then
    \begin{equation}
        \mathbb{P}(\left\| \mathbf{A} \right\|_2 \ge 2 \sqrt{I \lor J} + \delta) \le 2 \exp(-\tfrac1{2} \delta^2).
    \end{equation}

Let $Q$ be a mean-field variational posterior and $P=\mathcal{N}(\mathbf{0},\mathbf{I})$ denote the prior over a neural network with $L$ hidden layers and $M$ neurons per hidden layer.
    Suppose $\phi_{\text{e}}=\alpha$ for some $\alpha \in \mathbb{R}$ and $\phi\colon \mathbb{R} \to \mathbb{R}$ is $1$-Lipschitz.
    Let $\mathbf{x} \in \mathbb{R}^{D_{\text{i}}}$ and let $\widetilde{\mathbf{f}}_{\theta}(\mathbf{x}) = \mathbf{f}_\theta(\mathbf{x}) - \tfrac\alpha{\sqrt{M}}\mathbf{W}_{L+1}\mathbf{1} - \mathbf{b}_{L+1}$ denote the network output excluding final bias and even part of the final activation. Then 
    \begin{equation}
        \left\| \mathbb{E}_Q[\tilde{\mathbf{f}}_{\bm{\uptheta}}^2(\mathbf{x})] - \mathbb{E}_P[\tilde{\mathbf{f}}_{\bm{\uptheta}}^2(\mathbf{x})] \right\|_\infty
        \le
            c_1L^{1/2} \rho_{\alpha, M}^L
            \frac
                {\alpha^2 + 1 + \tfrac1{D_{\text{i}}}\left\| \mathbf{x} \right\|_2^2}
                {\sqrt{M}}  
            \sqrt{\operatorname{KL}(\ensuremath{Q}, \ensuremath{P})} (2\operatorname{KL}(\ensuremath{Q}, \ensuremath{P}) \lor 1)^{L+\tfrac12},
    \end{equation}
    where $c_1 = 16 + 25\sqrt{2} \in (51, 52)$ and where $\rho_{\alpha, M} \in (17, 97)$ is defined in 35.

We have,
    \begin{align}
        \|\mathbb{E}_{\ensuremath{Q}}[\phi_{\text{o}}(\mathbf{z}_{L})^2 ]- \mathbb{E}_{\ensuremath{P}}[\phi_{\text{o}}(\mathbf{z}_{L})^2]\|_2
        &\le 8 \sqrt{2} \rho_{\alpha, M}^{L-\tfrac12} L^{1/2} K (K^2 \lor 1)^{L-\tfrac12}\left(\alpha^2 + 1\lor \tfrac1{D_{\text{i}}}\|\mathbf{x}\|^2_2\right),
    \end{align}
    where $K = \sqrt{2 \operatorname{KL}(\ensuremath{Q}, \ensuremath{P})}$ and 
    \begin{equation}
        \rho_{\alpha, M} =
        \begin{cases}
        12(2+\sqrt{2\pi}) \in (54,55) & \alpha=0, M<36 \\
        \tfrac23(13+2\sqrt{43}) \in (17,18) & \alpha=0, M\ge 36 \\
        28 + \sqrt{793} \in (56,57) & \alpha\neq 0, M<36 \\
        48 + \sqrt{2353} \in (96,97) & \alpha\neq 0, M\ge 36. \\
    \end{cases}
\end{equation}

Define $\mathbf{\Sigma}_{Q} =\mathbb{E}_{\ensuremath{Q}}[\mathbf{w}_{L+1}\mathbf{w}_{L+1}^{\text{\textsf{T}}}] -  \mathbb{E}_{\ensuremath{Q}}[\mathbf{w}_{L+1}]\mathbb{E}_{\ensuremath{Q}}[\mathbf{w}_{L+1}]^{\text{\textsf{T}}}$, which is a diagonal matrix with the variances of $\mathbf{w}_{L+1}$ as entries. Let 
\begin{align}
    D^i_{\ensuremath{P}}(\mathbf{x}) &= \tfrac{1}{M}\operatorname{tr}(\mathbb{E}_{\ensuremath{P}}[\mathbf{w}_{L+1}\mathbf{w}_{L+1}^{\text{\textsf{T}}}]\mathbb{E}_{\ensuremath{P}}[\phi_{\text{o}}(\mathbf{z}_{L})\phi_{\text{o}}(\mathbf{z}_{L})^{\text{\textsf{T}}}])\\
        D^i_{\ensuremath{Q}}(\mathbf{x}) &=\tfrac{1}{M}\operatorname{tr}(\mathbf{\Sigma}_{Q}\mathbb{E}_{\ensuremath{Q}}[\phi_{\text{o}}(\mathbf{z}_{L})\phi_{\text{o}}(\mathbf{z}_{L})^{\text{\textsf{T}}}])
\end{align}
Then,
\begin{align}
    |D^{i}_{\ensuremath{Q}}(\mathbf{x}) - D^{i}_{\ensuremath{P}}(\mathbf{x})| 
    &\leq  
    \left(16 + \sqrt{2}\right) L^{1/2}
    \rho_{\alpha, M}^{L}\frac{\alpha^2 + 1\lor \tfrac1{D_{\text{i}}}\|\mathbf{x}\|^2_2}{\sqrt{M}}  \sqrt{\operatorname{KL}(\ensuremath{Q},\ensuremath{P})} (2 \operatorname{KL}(\ensuremath{Q},\ensuremath{P}) \lor 1)^{L+\tfrac12}
\end{align}
where $\rho_{\alpha, M} \in (17, 97)$ is defined in 35.

Define $
O^i_{\ensuremath{Q}}(\mathbf{x}) = \frac{1}{M}\mathbb{E}_{\ensuremath{Q}}[\mathbf{w}_{L+1}]^{\text{\textsf{T}}}\mathbb{E}_{\ensuremath{Q}}[\phi_{\text{o}}(\mathbf{z}_{L})\phi_{\text{o}}(\mathbf{z}_{L})^{\text{\textsf{T}}}]\mathbb{E}_{\ensuremath{Q}}[\mathbf{w}_{L+1}]$.
Then,



\begin{equation}
    |O^i_{\ensuremath{Q}}(\mathbf{x})| \leq 48\gamma_\alpha^{L}\frac{\alpha^2 + 1\lor \tfrac1{D_{\text{i}}}\|\mathbf{x}\|^2_2}{\sqrt{M}}
    \operatorname{KL}(\ensuremath{Q},\ensuremath{P})(2\operatorname{KL}(\ensuremath{Q},\ensuremath{P}) \lor 1)^{L},
\end{equation}
where $\gamma_\alpha = 9 + \sqrt{83} \in (18,19)$ if $\alpha=0$ and $\gamma_\alpha = 55$ if $\alpha\neq0$.

\begin{equation}
    \  \|\mathbb{E}_{\ensuremath{Q}}[\phi_{\text{o}}(\mathbf{z}_{L}(\mathbf{x}))\phi_{\text{o}}(\mathbf{z}_{L}(\mathbf{x}))^{\text{\textsf{T}}}]\|_2 
    \leq 24\sqrt{M} \left(\gamma_{\alpha,M}(K^2 \lor 1)\right)^{L}\left(\alpha^2 + 1\lor \tfrac1{D_{\text{i}}}\|\mathbf{x}\|^2_2\right),
\end{equation}
where $K=\sqrt{\operatorname{KL}(\ensuremath{Q},\ensuremath{P})}$ and $\gamma_{\alpha,M} \in (17,97)$ is defined in 31.

For $\alpha=0$ and $1 \leq \ell \leq L$, we have
    \begin{equation}
        \left\| \mathbb{E}[\mathbf{z}_\ell^2] \right\|_\infty \leq (\gamma_{\alpha, M} (1 \lor K^2))^{\ell} (1\lor \tfrac1{D_{\text{i}}}\|\mathbf{x}\|^2_2),
    \end{equation}
    with $\gamma_{\alpha, M}$ taking the value $\tfrac23(13+2\sqrt{43} \in (17,18)$ if $M\ge 36$ and $2(6+\sqrt{38}) \in (24,25)$ if $1\le M < 36$.
    On the other hand, for $\alpha \neq 0$ and $1 \leq \ell \le L$, we have
    \begin{equation}
        \alpha^2 + \left\| \mathbb{E}[\mathbf{z}_\ell^2] \right\|_\infty \leq (\gamma_{\alpha, M} (1 \lor K^2))^{\ell} (\alpha^2 + 1\lor \tfrac1{D_{\text{i}}} \|\mathbf{x}\|^2_2),
    \end{equation}
    with $\gamma_{\alpha, M}$ taking the value $28 + \sqrt{793} \in (56,57)$ if $M\ge 36$ and $48 + \sqrt{2353} \in (96,97)$ if $1\le M < 36$.
